"""Exercise real DWM region mirrors with pixels generated by this test only.

Build first:
  npm run build
  npm run tauri build -- --debug --no-bundle --config tests/native-webview.config.json
Run:
  python tests/region-mirror-native-smoke.py --exe src-tauri/target/debug/DtKit.exe

The shared harness rejects production storage. All window messages target the
launched test PID or our own Tk source. Selection briefly moves the pointer only
inside that generated source; it never clicks another application's window.
Pixel reads cover only the test mirror, and no desktop screenshots are saved.
"""

import argparse
import ctypes
import importlib.util
import os
import time
from ctypes import wintypes
from pathlib import Path
from uuid import uuid4

from playwright.sync_api import Error, sync_playwright


spec = importlib.util.spec_from_file_location(
    'native_webview', Path(__file__).with_name('native-webview-ui-smoke.py'))
native = importlib.util.module_from_spec(spec)
spec.loader.exec_module(native)

USER = ctypes.WinDLL('user32', use_last_error=True)
GDI = ctypes.WinDLL('gdi32', use_last_error=True)
DWM = ctypes.WinDLL('dwmapi', use_last_error=True)
USER.GetAncestor.argtypes = [wintypes.HWND, wintypes.UINT]
USER.GetAncestor.restype = wintypes.HWND
USER.WindowFromPoint.argtypes = [wintypes.POINT]
USER.WindowFromPoint.restype = wintypes.HWND
USER.mouse_event.argtypes = [wintypes.DWORD, wintypes.DWORD, wintypes.DWORD,
                             wintypes.DWORD, ctypes.c_size_t]
USER.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
USER.GetWindowThreadProcessId.restype = wintypes.DWORD
USER.GetWindowRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
USER.GetClientRect.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.RECT)]
USER.ClientToScreen.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.POINT)]
USER.GetClassNameW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
USER.GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
USER.GetWindowLongPtrW.argtypes = [wintypes.HWND, ctypes.c_int]
USER.GetWindowLongPtrW.restype = ctypes.c_ssize_t
USER.GetDpiForWindow.argtypes = [wintypes.HWND]
USER.GetDpiForWindow.restype = wintypes.UINT
USER.MonitorFromWindow.argtypes = [wintypes.HWND, wintypes.DWORD]
USER.MonitorFromWindow.restype = wintypes.HANDLE
USER.IsWindow.argtypes = [wintypes.HWND]
USER.IsWindowVisible.argtypes = [wintypes.HWND]
USER.IsIconic.argtypes = [wintypes.HWND]
USER.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
USER.SetWindowPos.argtypes = [wintypes.HWND, wintypes.HWND, ctypes.c_int,
                              ctypes.c_int, ctypes.c_int, ctypes.c_int, wintypes.UINT]
USER.SetForegroundWindow.argtypes = [wintypes.HWND]
USER.SendMessageTimeoutW.argtypes = [wintypes.HWND, wintypes.UINT,
                                    wintypes.WPARAM, wintypes.LPARAM, wintypes.UINT,
                                    wintypes.UINT, ctypes.POINTER(ctypes.c_size_t)]
USER.SendMessageTimeoutW.restype = wintypes.LPARAM
USER.GetDC.argtypes = [wintypes.HWND]
USER.GetDC.restype = wintypes.HDC
USER.ReleaseDC.argtypes = [wintypes.HWND, wintypes.HDC]
GDI.GetPixel.argtypes = [wintypes.HDC, ctypes.c_int, ctypes.c_int]
GDI.GetPixel.restype = wintypes.DWORD
ENUM = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
USER.EnumWindows.argtypes = [ENUM, wintypes.LPARAM]

COLORS = [(29, 190, 119), (231, 115, 49), (42, 145, 229), (224, 194, 48)]
ALTERNATE = (174, 65, 215)
CROP = (60, 80, 380, 260)


class MonitorInfo(ctypes.Structure):
    _fields_ = [('cbSize', wintypes.DWORD), ('rcMonitor', wintypes.RECT),
                ('rcWork', wintypes.RECT), ('dwFlags', wintypes.DWORD)]


USER.GetMonitorInfoW.argtypes = [wintypes.HANDLE, ctypes.POINTER(MonitorInfo)]


def monitor_work_area(handle):
    info = MonitorInfo(cbSize=ctypes.sizeof(MonitorInfo))
    assert USER.GetMonitorInfoW(USER.MonitorFromWindow(handle, 2), ctypes.byref(info))
    return info.rcWork


def invoke(page, command, args=None):
    return page.evaluate('''({command,args}) =>
        Object.getPrototypeOf(window.__TAURI__).core.invoke(command,args)''',
                         {'command': command, 'args': args or {}})


def dismiss(page):
    try:
        invoke(page, 'dismiss_quick_host')
    except Error as error:
        if not page.is_closed() and 'closed' not in str(error):
            raise


def pid_of(handle):
    pid = wintypes.DWORD()
    USER.GetWindowThreadProcessId(handle, ctypes.byref(pid))
    return pid.value


def window_bounds(handle, client=False):
    rect = wintypes.RECT()
    assert (USER.GetClientRect if client else USER.GetWindowRect)(handle, ctypes.byref(rect))
    if client:
        origin = wintypes.POINT()
        assert USER.ClientToScreen(handle, ctypes.byref(origin))
        return origin.x, origin.y, rect.right, rect.bottom
    return rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top


def near(actual, expected, tolerance=16):
    return max(abs(left - right) for left, right in zip(actual, expected)) <= tolerance


class Windows:
    """Require ownership before any native mutation or input message."""

    def __init__(self, app_pid):
        self.app_pid = app_pid

    def check(self, handle):
        assert USER.IsWindow(handle) and pid_of(handle) in (self.app_pid, os.getpid()), handle

    def mirrors(self, selecting=None):
        found = []

        def visit(handle, _):
            if pid_of(handle) != self.app_pid:
                return True
            name = ctypes.create_unicode_buffer(128)
            USER.GetClassNameW(handle, name, len(name))
            if name.value != 'DtKitRegionMirror':
                return True
            title = ctypes.create_unicode_buffer(512)
            USER.GetWindowTextW(handle, title, len(title))
            picker = title.value == 'DtKit · 框选悬浮区域'
            if selecting is None or selecting == picker:
                found.append(handle)
            return True

        assert USER.EnumWindows(ENUM(visit), 0)
        return found

    def app_windows(self):
        found = []

        def visit(handle, _):
            if pid_of(handle) == self.app_pid:
                found.append(handle)
            return True

        assert USER.EnumWindows(ENUM(visit), 0)
        return set(found)

    def message(self, handle, message, key=0, coordinates=0):
        self.check(handle)
        result = ctypes.c_size_t()
        assert USER.SendMessageTimeoutW(handle, message, key, coordinates, 2, 5000,
                                        ctypes.byref(result)), ctypes.get_last_error()

    def show(self, handle, command):
        self.check(handle)
        USER.ShowWindow(handle, command)

    def position(self, handle, x, y, width, height, topmost=False):
        self.check(handle)
        # HWND_TOPMOST is -1; otherwise retain the existing Z order.
        assert USER.SetWindowPos(handle, -1 if topmost else 0, x, y, width, height,
                                 0x0040 | (0 if topmost else 0x0004))

    def drag(self, picker, source, first, last):
        self.check(source)
        left, top, width, height = window_bounds(source, client=True)
        for x, y in (first, last):
            assert 0 <= x < width and 0 <= y < height
        saved = wintypes.POINT()
        assert USER.GetCursorPos(ctypes.byref(saved))
        try:
            assert USER.SetCursorPos(left + first[0], top + first[1])
            self.message(picker, 0x0201, 1)  # WM_LBUTTONDOWN reads GetCursorPos.
            assert USER.SetCursorPos(left + last[0], top + last[1])
            self.message(picker, 0x0200, 1)
            self.message(picker, 0x0202)
        finally:
            USER.SetCursorPos(saved.x, saved.y)

    def click(self, point, expected_root):
        self.check(expected_root)
        # Prove the physical input will reach a window owned by this test.
        assert USER.GetAncestor(USER.WindowFromPoint(wintypes.POINT(*point)), 2) == expected_root
        saved = wintypes.POINT()
        assert USER.GetCursorPos(ctypes.byref(saved))
        try:
            assert USER.SetCursorPos(*point)
            USER.mouse_event(0x0002, 0, 0, 0, 0)
            USER.mouse_event(0x0004, 0, 0, 0, 0)
        finally:
            USER.SetCursorPos(saved.x, saved.y)

    def physical_drag(self, picker, source, first, last, pump):
        self.check(source)
        x, y, width, height = window_bounds(source, client=True)
        saved = wintypes.POINT()
        assert USER.GetCursorPos(ctypes.byref(saved))
        try:
            for point in (first, last):
                assert 0 <= point[0] < width and 0 <= point[1] < height
                assert USER.GetAncestor(USER.WindowFromPoint(
                    wintypes.POINT(x + point[0], y + point[1])), 2) == picker
            assert USER.SetCursorPos(x + first[0], y + first[1])
            USER.mouse_event(0x0002, 0, 0, 0, 0)
            pump()
            assert USER.SetCursorPos(x + last[0], y + last[1])
            USER.mouse_event(0x0004, 0, 0, 0, 0)
            pump()
        finally:
            USER.SetCursorPos(saved.x, saved.y)


class Source:
    def __init__(self, windows, work):
        import tkinter as tk
        self.root = tk.Tk()
        self.root.title('DtKit isolated mirror source ' + uuid4().hex)
        self.root.geometry('560x400')
        self.canvas = tk.Canvas(self.root, background='#344155', highlightthickness=0)
        self.canvas.pack(fill='both', expand=True)
        self.clicks = 0

        def clicked(_):
            self.clicks += 1

        self.canvas.bind('<Button-1>', clicked)
        self.blocks = []
        left, top, right, bottom = CROP
        for index, color in enumerate(COLORS):
            x = left + (right - left) // 2 * (index % 2)
            y = top + (bottom - top) // 2 * (index // 2)
            self.blocks.append(self.canvas.create_rectangle(
                x, y, x + (right - left) // 2, y + (bottom - top) // 2,
                fill='#%02x%02x%02x' % color, outline=''))
        self.root.update()
        self.handle = USER.GetAncestor(self.root.winfo_id(), 2)
        assert pid_of(self.handle) == os.getpid(), self.handle
        x, y, width, height = window_bounds(self.handle)
        windows.position(self.handle, work.left + 24, work.top + 100,
                         width, height, topmost=True)
        self.update()
        self.original = window_bounds(self.handle)

    def update(self):
        if self.root is not None:
            self.root.update_idletasks()
            self.root.update()

    def color(self, color):
        self.canvas.itemconfigure(self.blocks[0], fill='#%02x%02x%02x' % color)
        self.update()

    def close(self):
        if self.root is not None:
            self.root.destroy()
            self.root = None


def sample_points(handle, compact=False):
    """Match the public picture's expected letterbox without reading app state."""
    x, y, width, height = window_bounds(handle, client=True)
    header = 0 if compact else 36 * max(96, USER.GetDpiForWindow(handle)) // 96
    available_width, available_height = max(1, width - 2), max(1, height - header - 1)
    ratio = min(available_width / 320, available_height / 180)
    content_width, content_height = round(320 * ratio), round(180 * ratio)
    left = x + 1 + (available_width - content_width) // 2
    top = y + header + (available_height - content_height) // 2
    points = [(left + round(content_width * fx), top + round(content_height * fy))
              for fx, fy in ((.25, .25), (.75, .25), (.25, .75), (.75, .75))]
    return points, (left, top, content_width, content_height)


def pixels(handle, points):
    assert USER.IsWindowVisible(handle) and not USER.IsIconic(handle)
    x, y, width, height = window_bounds(handle, client=True)
    assert all(x <= px < x + width and y <= py < y + height for px, py in points)
    DWM.DwmFlush()
    dc = USER.GetDC(None)
    assert dc
    try:
        values = [GDI.GetPixel(dc, px, py) for px, py in points]
        assert all(value != 0xFFFFFFFF for value in values), values
        return [(value & 255, value >> 8 & 255, value >> 16 & 255) for value in values]
    finally:
        USER.ReleaseDC(None, dc)


def scenario(owner, context, process):
    windows = Windows(process.pid)
    controller = owner
    work = wintypes.RECT()
    assert USER.SystemParametersInfoW(48, 0, ctypes.byref(work), 0)  # SPI_GETWORKAREA
    fixture = Source(windows, work)

    def until(predicate, label, timeout=15):
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            fixture.update()
            if controller.is_closed():
                time.sleep(.05)
            else:
                controller.wait_for_timeout(50)
            if process.poll() is not None:
                raise AssertionError(f'Application exited during {label}: {process.returncode}')
            if predicate():
                return
        raise AssertionError('Timed out: ' + label)

    def items():
        return invoke(controller, 'list_region_mirrors')

    def info(identifier):
        return next((item for item in items() if item['id'] == identifier), None)

    def control(identifier, action, value=None):
        args = {'id': identifier, 'action': action}
        if value is not None:
            args['value'] = value
        invoke(controller, 'control_region_mirror', args)

    def start(replace=None, source_handle=None):
        # Put only our generated source above any previous mirror for selection.
        source_handle = source_handle or fixture.handle
        x, y, width, height = window_bounds(source_handle)
        windows.position(source_handle, x, y, width, height, topmost=True)
        invoke(controller, 'start_region_mirror', {} if replace is None else {'replaceId': replace})
        until(lambda: len(windows.mirrors(selecting=True)) == 1, 'picker created')
        return windows.mirrors(selecting=True)[0]

    def confirm(picker, source_handle=None, crop=CROP):
        windows.drag(picker, source_handle or fixture.handle, crop[:2], crop[2:])
        windows.message(picker, 0x0100, 13)
        until(lambda: not windows.mirrors(selecting=True), 'confirmed region')
        until(lambda: all(item['status'] != 'selecting' for item in items()), 'live state published')

    def picture(handle, expected, compact=False, label='DWM pixels updated'):
        points, _ = sample_points(handle, compact)
        until(lambda: all(near(value, target) for value, target in zip(
            pixels(handle, points), expected)), label)

    def place(handle, width=440, height=360):
        windows.position(handle, max(work.left, work.right - width - 24),
                         work.top + 20, width, height, topmost=True)

    try:
        until(lambda: owner.evaluate('window.__DTKIT_TOOL_PAGE__?.ready === true'), 'tool ready')
        assert items() == [], items()
        baseline = invoke(owner, 'get_resource_snapshot')['webviewCount']

        picker = start()
        assert len(items()) == 1 and items()[0]['status'] == 'selecting'
        windows.message(picker, 0x0100, 27)
        until(lambda: not items() and not windows.mirrors(), 'Esc cancellation cleaned up')

        # A too-small region must keep the picker alive and allow a real retry.
        picker = start()
        windows.drag(picker, fixture.handle, (80, 100), (90, 110))
        windows.message(picker, 0x0100, 13)
        assert windows.mirrors(selecting=True) == [picker]
        assert items()[0]['status'] == 'selecting'
        windows.drag(picker, fixture.handle, CROP[:2], CROP[2:])
        clicks_before = fixture.clicks

        def pump_input():
            fixture.update()
            owner.wait_for_timeout(100)
            fixture.update()

        # The already selected interior must continue receiving physical input.
        # A color-key hole would send this click to the source application.
        windows.physical_drag(picker, fixture.handle, (100, 120), (260, 200), pump_input)
        assert fixture.clicks == clicks_before
        windows.message(picker, 0x0100, 13)
        until(lambda: not windows.mirrors(selecting=True), 'physical reselection confirmed')
        assert (items()[0]['width'], items()[0]['height']) == (160, 80), items()
        control(items()[0]['id'], 'close')
        until(lambda: not items() and not windows.mirrors(), 'physical selection cleanup')
        picker = start()
        confirm(picker)
        entry = items()[0]
        identifier = entry['id']
        assert (entry['width'], entry['height']) == (320, 180), entry
        assert entry['status'] == 'live' and entry['pinned'] is True, entry
        handle = windows.mirrors(selecting=False)[0]
        place(handle)
        picture(handle, COLORS)
        fixture.color(ALTERNATE)
        picture(handle, [ALTERNATE, *COLORS[1:]], label='live color change reached DWM')
        fixture.color(COLORS[0])
        picture(handle, COLORS)

        # Check boundaries as well as quadrant centers, so a stretched image or
        # a wrong crop cannot pass by merely retaining the four colors.
        _, (left, top, width, height) = sample_points(handle)
        y = top + height // 4
        points = [(left + 3, y), (left + width // 2 - 4, y),
                  (left + width // 2 + 4, y), (left + width - 4, y)]
        actual = pixels(handle, points)
        if not all(near(value, target) for value, target in zip(actual, [COLORS[0]] * 2 + [COLORS[1]] * 2)):
            extended = wintypes.RECT()
            DWM.DwmGetWindowAttribute.argtypes = [wintypes.HWND, wintypes.DWORD, ctypes.c_void_p, wintypes.DWORD]
            DWM.DwmGetWindowAttribute(fixture.handle, 9, ctypes.byref(extended), ctypes.sizeof(extended))
            edge = pixels(handle, [(left + offset, y) for offset in range(30)])
            print('Crop failure: source window/client/extended=', window_bounds(fixture.handle),
                  window_bounds(fixture.handle, client=True), (extended.left, extended.top, extended.right, extended.bottom),
                  'mirror=', window_bounds(handle), 'picture=', (left, top, width, height),
                  'first TL offset=', next((index for index, value in enumerate(edge) if near(value, COLORS[0])), None), flush=True)
        assert all(near(value, target) for value, target in zip(actual, [COLORS[0]] * 2 + [COLORS[1]] * 2)), actual
        assert abs(width / height - 320 / 180) < .02, (width, height)
        # This deliberately tall mirror should have a visible letterbox.
        x, y, client_width, client_height = window_bounds(handle, client=True)
        header = 36 * max(96, USER.GetDpiForWindow(handle)) // 96
        assert top > y + header + 10
        assert near(pixels(handle, [(x + client_width // 2, y + header + 3)])[0], (18, 21, 29))
        assert invoke(owner, 'get_resource_snapshot')['webviewCount'] == baseline
        print('PASS: cancel/retry, physical crop, dynamic DWM pixels and aspect ratio', flush=True)

        control(identifier, 'pin')
        until(lambda: info(identifier)['pinned'] is False, 'unpin published')
        assert not USER.GetWindowLongPtrW(handle, -20) & 8
        control(identifier, 'pin')
        until(lambda: info(identifier)['pinned'] is True, 'pin published')
        assert USER.GetWindowLongPtrW(handle, -20) & 8

        control(identifier, 'compact')
        until(lambda: info(identifier)['compact'] is True, 'compact published')
        picture(handle, COLORS, compact=True)
        dpi = max(96, USER.GetDpiForWindow(handle))
        x, y, _, _ = window_bounds(handle)
        windows.position(handle, x, y, 120 * dpi // 96, 140 * dpi // 96)
        control(identifier, 'compact')
        until(lambda: info(identifier)['compact'] is False, 'toolbar restored')
        until(lambda: window_bounds(handle)[2] >= 180 * dpi // 96, 'toolbar remains usable after narrow compact mode')
        picture(handle, COLORS)

        control(identifier, 'compact')
        until(lambda: info(identifier)['compact'], 'compact for small scale presets')
        previous_width = 0
        for scale in (50, 100, 150, 200):
            control(identifier, 'scale', scale)
            # These presets fit on ordinary desktop work areas. A smaller
            # display may clamp the requested size to keep the mirror usable.
            requested_width = round(320 * scale / 100) + 2
            if (requested_width < work.right - work.left - 16
                    and 180 * scale / 100 + 1 < work.bottom - work.top - 16
                    and requested_width >= 120 * USER.GetDpiForWindow(handle) // 96):
                until(lambda: abs(window_bounds(handle)[2] - requested_width) <= 2,
                      f'{scale}% physical scale applied')
            else:
                owner.wait_for_timeout(200)
            actual_width = window_bounds(handle)[2]
            assert actual_width >= previous_width, (scale, actual_width, previous_width)
            previous_width = actual_width
            picture(handle, COLORS, compact=True)
        control(identifier, 'scale', 100)
        until(lambda: abs(window_bounds(handle)[2] - 322) <= 2, 'original crop size restored')
        control(identifier, 'compact')
        until(lambda: not info(identifier)['compact'], 'toolbar after scale presets')
        picture(handle, COLORS)

        control(identifier, 'opacity', 45)
        until(lambda: info(identifier)['opacity'] == 45, 'opacity published')
        points, _ = sample_points(handle)
        until(lambda: any(not near(color, target, 25) for color, target in
                          zip(pixels(handle, points), COLORS)), 'native alpha changes visible pixels')
        control(identifier, 'opacity', 100)
        until(lambda: info(identifier)['opacity'] == 100, 'opacity restored')
        picture(handle, COLORS, label='DWM remains visible after opacity change')
        control(identifier, 'clickThrough')
        until(lambda: info(identifier)['clickThrough'] is True, 'click-through published')
        assert USER.GetWindowLongPtrW(handle, -20) & 0x20
        fixture.color(ALTERNATE)
        picture(handle, [ALTERNATE, *COLORS[1:]], label='click-through keeps live DWM visible')
        source_left, source_top, _, _ = window_bounds(fixture.handle, client=True)
        windows.position(handle, source_left + 80, source_top + 80, 322, 240, topmost=True)
        click_point = (source_left + 240, source_top + 220)
        clicks_before = fixture.clicks
        windows.click(click_point, fixture.handle)
        until(lambda: fixture.clicks == clicks_before + 1, 'click-through delivers real mouse input to source')
        control(identifier, 'show')
        until(lambda: not info(identifier)['clickThrough'], 'show restores mouse interaction')
        windows.click(click_point, handle)
        fixture.update()
        owner.wait_for_timeout(200)
        fixture.update()
        assert fixture.clicks == clicks_before + 1, 'Recovered mirror still passes clicks through'
        control(identifier, 'clickThrough')
        until(lambda: info(identifier)['clickThrough'], 'click-through before offscreen recovery')
        windows.position(handle, work.right + 200, work.bottom + 200, 400, 300)
        windows.show(handle, 0)
        control(identifier, 'show')
        until(lambda: USER.IsWindowVisible(handle) and not info(identifier)['clickThrough'],
              'show recovered hidden click-through window')
        assert not USER.GetWindowLongPtrW(handle, -20) & 0x20
        x, y, width, height = window_bounds(handle)
        recovered_work = monitor_work_area(handle)
        assert recovered_work.left <= x < recovered_work.right and recovered_work.top <= y < recovered_work.bottom
        assert x + width <= recovered_work.right + 2 and y + height <= recovered_work.bottom + 2
        picture(handle, [ALTERNATE, *COLORS[1:]])
        windows.show(handle, 6)
        until(lambda: bool(USER.IsIconic(handle)), 'mirror minimized')
        control(identifier, 'show')
        until(lambda: USER.IsWindowVisible(handle) and not USER.IsIconic(handle),
              'show restores minimized mirror')
        picture(handle, [ALTERNATE, *COLORS[1:]])
        fixture.color(COLORS[0])
        picture(handle, COLORS)

        control(identifier, 'compact')
        control(identifier, 'opacity', 60)
        control(identifier, 'clickThrough')
        until(lambda: info(identifier)['compact'] and info(identifier)['clickThrough']
              and info(identifier)['opacity'] == 60, 'modified view settings')
        control(identifier, 'reset')
        until(lambda: not info(identifier)['compact'] and not info(identifier)['clickThrough']
              and info(identifier)['opacity'] == 100, 'reset view settings')
        picture(handle, COLORS)
        print('PASS: pin, compact, scale presets, opacity, click-through recovery and reset', flush=True)

        # Cancelling reselection must leave both the old ID and HWND intact.
        picker = start(identifier)
        windows.message(picker, 0x0100, 27)
        until(lambda: len(items()) == 1 and info(identifier) is not None,
              'cancelled replacement preserves existing mirror')
        assert USER.IsWindow(handle)
        place(handle)
        picture(handle, COLORS)
        picker = start(identifier)
        confirm(picker)
        until(lambda: len(items()) == 1 and info(identifier) is None and not USER.IsWindow(handle),
              'successful replacement closes old mirror')
        identifier = items()[0]['id']
        handle = windows.mirrors(selecting=False)[0]
        place(handle)
        picture(handle, COLORS)

        # Exercise a crop next to the source's right and bottom client edges.
        # The right edge exceeds the visible-frame QuerySourceSize coordinate,
        # which previously made ordinary resize borders corrupt the mapping.
        edge_crop = (239, 219, 559, 399)
        for block in fixture.blocks:
            fixture.canvas.move(block, 179, 139)
        fixture.update()
        picker = start(identifier)
        confirm(picker, crop=edge_crop)
        until(lambda: len(items()) == 1 and info(identifier) is None, 'edge crop replacement')
        identifier = items()[0]['id']
        handle = windows.mirrors(selecting=False)[0]
        place(handle)
        picture(handle, COLORS, label='right/bottom source-edge crop pixels')
        _, (edge_left, edge_top, edge_width, edge_height) = sample_points(handle)
        edge_pixels = pixels(handle, [(edge_left + 3, edge_top + edge_height // 4),
                                      (edge_left + edge_width - 4, edge_top + edge_height // 4),
                                      (edge_left + 3, edge_top + edge_height * 3 // 4),
                                      (edge_left + edge_width - 4, edge_top + edge_height * 3 // 4)])
        assert all(near(value, target) for value, target in zip(edge_pixels, COLORS)), edge_pixels

        source_x, source_y, source_width, source_height = fixture.original
        windows.position(fixture.handle, source_x + 20, source_y + 20,
                         source_width, source_height)
        until(lambda: info(identifier)['status'] == 'live', 'source movement remains live')
        picture(handle, COLORS)
        windows.position(fixture.handle, source_x, source_y,
                         source_width + 70, source_height + 60)
        until(lambda: info(identifier)['status'] == 'live', 'containing source resize remains live')
        fixture.color(ALTERNATE)
        picture(handle, [ALTERNATE, *COLORS[1:]], label='resized source remains dynamic')
        windows.position(fixture.handle, source_x, source_y, 300, 190)
        until(lambda: info(identifier)['status'] == 'resized', 'clipped crop reports resized')
        windows.position(fixture.handle, *fixture.original)
        until(lambda: info(identifier)['status'] == 'live', 'valid crop restored')
        picture(handle, [ALTERNATE, *COLORS[1:]])

        windows.show(fixture.handle, 6)
        until(lambda: info(identifier)['status'] == 'minimized', 'minimized source reported')
        control(identifier, 'source')
        until(lambda: not USER.IsIconic(fixture.handle) and info(identifier)['status'] == 'live',
              'source action restores minimized source')
        place(handle)
        picture(handle, [ALTERNATE, *COLORS[1:]])
        windows.show(fixture.handle, 0)
        until(lambda: info(identifier)['status'] == 'hidden', 'hidden source reported')
        control(identifier, 'source')
        until(lambda: USER.IsWindowVisible(fixture.handle) and info(identifier)['status'] == 'live',
              'source action restores hidden source')
        place(handle)
        picture(handle, [ALTERNATE, *COLORS[1:]])
        fixture.close()
        until(lambda: info(identifier)['status'] == 'closed', 'closed source reported')
        control(identifier, 'source')
        assert info(identifier)['status'] == 'closed' and process.poll() is None
        control(identifier, 'close')
        until(lambda: not items() and not windows.mirrors(), 'all native mirrors cleaned up')
        assert invoke(owner, 'get_resource_snapshot')['webviewCount'] == baseline
        print('PASS: replacement cancel/success, source move/resize/minimize/hide/close and cleanup', flush=True)

        # Another DtKit tool is a valid source. Generate its complete contents,
        # then close all WebViews to prove the native mirror owns its lifetime.
        previous_handles = windows.app_windows()
        invoke(owner, 'open_quick_host', {'target': {'kind': 'tool', 'toolId': 'html-preview'}})
        until(lambda: len(context.pages) == 2, 'same-process source tool opened')
        other = next(page for page in context.pages if page != owner)
        until(lambda: other.evaluate('window.__DTKIT_TOOL_PAGE__?.ready === true'), 'same-process source ready')
        other.evaluate('''colors => {
            const dpr = window.devicePixelRatio || 1;
            const board = document.createElement('div');
            Object.assign(board.style, {position:'fixed',inset:'0',background:'#344155',zIndex:'2147483647'});
            colors.forEach((color,index) => {
                const block=document.createElement('div');
                Object.assign(block.style,{position:'absolute',left:((60+160*(index%2))/dpr)+'px',
                    top:((80+90*Math.floor(index/2))/dpr)+'px',width:(160/dpr)+'px',height:(90/dpr)+'px',
                    background:'rgb('+color.join(',')+')'});
                board.append(block);
            });
            document.body.append(board);
        }''', COLORS)
        until(lambda: len(windows.app_windows() - previous_handles) == 1, 'same-process native source handle')
        source_handle = next(iter(windows.app_windows() - previous_handles))
        windows.position(source_handle, work.left + 24, work.top + 100, 560, 400, topmost=True)
        picker = start(source_handle=source_handle)
        confirm(picker, source_handle=source_handle)
        until(lambda: len(items()) == 1 and items()[0]['status'] == 'live', 'same-process source selected')
        identifier = items()[0]['id']
        handle = windows.mirrors(selecting=False)[0]
        place(handle)
        picture(handle, COLORS, label='same-process source DWM pixels')
        controller = other
        dismiss(owner)
        until(lambda: owner.is_closed(), 'manager page closed')
        assert info(identifier)['status'] == 'live' and USER.IsWindow(handle)
        snapshot = invoke(other, 'get_resource_snapshot')
        assert snapshot['webviewCount'] == 1 and snapshot['toolOnly'] is True, snapshot
        picture(handle, COLORS, label='mirror survives manager closure')
        dismiss(other)
        until(lambda: other.is_closed(), 'last source WebView closed')
        until(lambda: USER.IsWindow(handle), 'native mirror keeps tool-only process alive')
        time.sleep(1.2)
        assert process.poll() is None and USER.IsWindow(handle), 'Mirror did not retain native lifetime'
        windows.message(handle, 0x0010)
        native.wait_until(lambda: process.poll() is not None)
        assert process.returncode == 0, process.returncode
        print('PASS: same-process source, manager closure, native-only lifetime and final-window exit', flush=True)
    finally:
        # End only this run's region mirrors; no process-name based termination.
        for mirror in windows.mirrors():
            try:
                windows.message(mirror, 0x0010)
            except Exception:
                pass
        fixture.close()


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--exe', type=Path, required=True)
    args = parser.parse_args()
    executable = args.exe.resolve()
    assert executable.is_file(), executable
    assert os.name == 'nt', 'This test needs a real interactive Windows desktop with DWM.'
    try:
        USER.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4))
    except OSError:
        ctypes.windll.shcore.SetProcessDpiAwareness(2)
    with sync_playwright() as playwright:
        native.run_case(playwright, executable, ['--tool', 'region-mirror'], scenario)
